code.cpp:
class Solution {
public:
    int distinctPrimeFactors(vector<int>& nums) {
        unordered_set<int> primes;
        for (int num : nums) {
            for (int d = 2; d * d <= num; d++) {
                while (num % d == 0) {
                    primes.insert(d);
                    num /= d;
                }
            }
            if (num > 1) {
                primes.insert(num);
            }
        }
        return primes.size();
    }
};
